"""UI script test generated from the API contract. Do not edit; fix the script instead."""
import re

from fastapi.testclient import TestClient

from backend.main import app

client = TestClient(app)


def test_script_calls_every_endpoint():
    js = client.get('/static/app.js').text
    assert 'fetch' in js
    assert '/api/todos' in js


def test_list_view_shows_every_field_of_an_item():
    js = client.get('/static/app.js').text
    for field in ['title', 'description', 'priority', 'done']:
        # read as a property of an item (item.field, item['field']) or named for UI.renderList (a quoted name in a list or object);
        # the add form's own use of the name does not count
        assert re.search(r'(?:[.]|\[\s*[\'"])' + field + r'\b|[\'"]' + field + r'[\'"]\s*[\],}]', js), (
            f"the list never uses the item field '{field}'. Show EVERY important field of each item, not just the title "
            "(for example the description as muted text and a priority, status or category as a badge).")


def test_categories_are_shown_as_labels_not_numbers():
    js = client.get('/static/app.js').text
    page = client.get('/').text
    for field, labels in {'priority': ['Low', 'Medium', 'High']}.items():
        for label in labels:
            assert label in page + js, f"the label '{label}' of '{field}' appears nowhere: build the select from the contract's labels"
        assert not re.search(r'<option[^>]*value=["\']\d+["\']', page), f"a select has a numeric option value; '{field}' must send its label (High), not a number (3)"
        assert not re.search(r'(?:parseInt|parseFloat|Number)\([^)]*\b' + field + r'\b', js), f"'{field}' is converted to a number; send and show the label as it is"
        assert not re.search(r'\b' + field + r'\s*:\s*-?\d', js), f"'{field}' is given a numeric value; use one of its labels {labels}"



def balanced(js, start, open_ch, close_ch):
    """Index just after the bracket that closes the one opened just before js[start]."""
    depth, i = 1, start
    while i < len(js) and depth:
        depth += 1 if js[i] == open_ch else -1 if js[i] == close_ch else 0
        i += 1
    return i


def action_spans(js):
    """(start, end) of every `actions: [ ... ]` array: the buttons of a list row."""
    return [(m.end(), balanced(js, m.end(), "[", "]")) for m in re.finditer(r"actions\s*:\s*\[", js)]


_NAMED = re.compile(r"function\s+(\w+)\s*\(|(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?(?:function\s*\w*\s*)?(?:\([^)]*\)|\w+)\s*(?:=>)?\s*(?=\{)")


def named_functions(js):
    """name -> (start, end) of the body of every named function, or arrow function assigned to a name."""
    out = {}
    for m in _NAMED.finditer(js):
        brace = js.find("{", m.end())
        if brace != -1:
            out.setdefault(m.group(1) or m.group(2), (brace + 1, balanced(js, brace + 1, "{", "}")))
    return out


def reachable_bodies(js):
    """Bodies of the functions a list button can reach: named in an action, or called by a function that is reachable."""
    funcs = named_functions(js)
    names = {n for a, b in action_spans(js) for n in re.findall(r"(\w+)\s*\(", js[a:b])}
    seen = set()
    while names - seen:
        name = (names - seen).pop()
        seen.add(name)
        if name in funcs:
            a, b = funcs[name]
            names |= set(re.findall(r"(\w+)\s*\(", js[a:b]))
    return [funcs[n] for n in seen if n in funcs]


def called_from_a_button(js, method, base, suffix=""):
    """True when a fetch of `method` to `base`/... sits inside an action or inside a function that an action reaches."""
    spans = action_spans(js) + reachable_bodies(js)
    for m in re.finditer(r"fetch\(", js):
        window = js[m.end():balanced(js, m.end(), "(", ")")]  # the arguments of this one fetch call
        if base in window and re.search(r"method\s*:\s*['\"`]" + method, window, re.I) and (not suffix or suffix in window):
            if any(a <= m.start() < b for a, b in spans):
                return True
    return False


def test_every_item_endpoint_has_a_button_in_the_list():
    js = client.get('/static/app.js').text
    assert 'actions' in js, "the list rows have no buttons: pass actions: [{ label: 'Delete', ... }] to UI.renderList"
    assert called_from_a_button(js, 'PUT', '/api/todos/', ''), (
        "PUT /api/todos/{id} is never called from a list button: add a button to `actions` of every row whose onClick leads to this call")
    assert called_from_a_button(js, 'DELETE', '/api/todos/', ''), (
        "DELETE /api/todos/{id} is never called from a list button: add a button to `actions` of every row whose onClick leads to this call")
    assert re.search(r'edit', js, re.I), "add an Edit button to every row"
    assert re.search(r'delete|remove', js, re.I), "add a Delete button to every row"
    assert 'onToggle' in js, "done is a yes/no field: show a checkbox in each row so ticking it saves at once (done: 'done', onToggle: (checked) => save(item.id, { ...item, done: checked }))"



def test_the_list_can_be_filtered():
    js = client.get('/static/app.js').text
    assert '.filter(' in js, "the page must offer the filter it promises: a select with All plus the labels, applied with items.filter(...) before UI.renderList"

